                sc[i] = sa[i] * sb[i] % mod;
            }
            for (int i = 0; i < n - 1; i++)
            {
                c[i] = (sc[i] - sc[i + 1] + mod) % mod;
            }
            c[n - 1] = sc[n - 1];
