            for (int k = 0; k < limit; k++)
            {
                long best = long.MaxValue;
                for (int i = 0; i < aLen; i++)
                {
                    int j = k - i;
                    if (j >= 0 && j < bLen)
                    {
                        long sum = a[i] + b[j];
                        if (sum < best)
                        {
                            best = sum;
                        }
                    }
                }
                c[k] = best;
            }
        }

        public static void MaxPlusGeneral(long* a, int aLen, long* b, int bLen, long* c)
        {
            int limit = aLen + bLen - 1;
            for (int k = 0; k < limit; k++)
            {
                long best = long.MinValue;
                for (int i = 0; i < aLen; i++)
                {
                    int j = k - i;
                    if (j >= 0 && j < bLen)
                    {
                        long sum = a[i] + b[j];
                        if (sum > best)
                        {
                            best = sum;
                        }
                    }
                }
                c[k] = best;
            }
        }

