        }

        public static void MinPlusConvexConvex(long* a, int n, long* b, int m, long* c)
        {
            c[0] = a[0] + b[0];
            int i = 0;
            int j = 0;
            int k = 1;
            while (i < n - 1 && j < m - 1)
            {
                long diffA = a[i + 1] - a[i];
                long diffB = b[j + 1] - b[j];
                if (diffA < diffB)
                {
                    c[k] = c[k - 1] + diffA;
                    i++;
                }
                else
                {
                    c[k] = c[k - 1] + diffB;
                    j++;
                }
                k++;
            }
            while (i < n - 1)
            {
                c[k] = c[k - 1] + (a[i + 1] - a[i]);
                i++;
                k++;
            }
            while (j < m - 1)
            {
                c[k] = c[k - 1] + (b[j + 1] - b[j]);
                j++;
                k++;
            }
        }

        public static void MaxPlusConcaveConcave(long* a, int n, long* b, int m, long* c)
        {
            c[0] = a[0] + b[0];
            int i = 0;
            int j = 0;
            int k = 1;
            while (i < n - 1 && j < m - 1)
            {
                long diffA = a[i + 1] - a[i];
                long diffB = b[j + 1] - b[j];
                if (diffA > diffB)
