                    c[k] = c[k - 1] + diffB;
                    j++;
                }
                k++;
            }
            while (i < n - 1)
            {
                c[k] = c[k - 1] + (a[i + 1] - a[i]);
                i++;
                k++;
            }
            while (j < m - 1)
            {
                c[k] = c[k - 1] + (b[j + 1] - b[j]);
                j++;
                k++;
            }
        }

        private static void SolveMinPlus(
            int l, int r,
            int optL, int optR,
            long* a, int n,
