namespace IAFahim.Optimization.DivideConquer
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class OnlineDp
    {
        public static void Recompute(long* dp, int l, int r, int optL, int optR, int k, delegate*<int,int,long> calc)
        {
            if (l > r) return;
            int mid = (l + r) >> 1;
            long best = long.MaxValue;
            int bestPos = -1;
            int start = Math.Max(optL, mid - k);
            int end = Math.Min(optR, mid);
            for (int j = start; j <= end; j++)
            {
                long cand = calc(mid, j) + (j > 0 ? dp[j - 1] : 0);
                if (cand < best) { best = cand; bestPos = j; }
            }
            dp[mid] = best;
            Recompute(dp, l, mid - 1, optL, bestPos, k, calc);
            Recompute(dp, mid + 1, r, bestPos, optR, k, calc);
        }
    }
}

cs_files.DequeOpt.cs:
namespace IAFahim.Optimization.DivideConquer
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class DequeOpt
    {
        public struct Quad
        {
            public long A, B, C;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long Eval(Quad q, long x)
        {
            return (q.A * x + q.B) * x + q.C;
        }

        // Crossing abscissa of two quadratics that share the same leading
        // coefficient A (the x^2 terms cancel, leaving a linear equation):
        //   p.B*x + p.C = q.B*x + q.C  =>  x = (q.C - p.C) / (p.B - q.B).
        // Caller (Run) maintains a lower envelope where consecutive deque
        // members differ in B, so the denominator is non-zero by design.
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long IntersectX(Quad p, Quad q)
        {
            return (q.C - p.C) / (p.B - q.B);
        }

        public static void Run(long* dp, int n, Quad* quads, int* deque, int* head, int* tail)
        {
            int h = 0;
            int t = 0;
            for (int i = 0; i < n; i++)
            {
                long frontVal = Eval(quads[deque[h]], i);
                while (t - h > 1)
                {
                    long nextVal = Eval(quads[deque[h + 1]], i);
                    if (frontVal < nextVal) break;
                    frontVal = nextVal;
                    h++;
                }
                dp[i] = frontVal;
                Quad newQ = quads[i + 1];
                while (t - h > 1 && IntersectX(quads[deque[t - 1]], quads[deque[t - 2]]) >= IntersectX(quads[deque[t - 1]], newQ))
                    t--;
                deque[t++] = i + 1;
            }
            *head = h;
            *tail = t;
        }
    }
}

cs_files.MaxIndependentSet.cs:
namespace IAFahim.Optimization.Exact
{
    using System;

    public static unsafe class MaxIndependentSet
    {
        public static int Run(int n, bool* adj, int* used, int* best, int* tmp)
        {
            *best = 0;
            Search(n, adj, used, 0, best, 0, 0, tmp);
            return *best;
        }

        private static void Search(int n, bool* adj, int* used, int v, int* best, int cur, int depth, int* tmp)
        {
            if (v == n) { if (cur > *best) *best = cur; return; }

            if (CanIncludeNode(n, adj, used, v))
            {
                used[v] = 1;
                Search(n, adj, used, v + 1, best, cur + 1, depth + 1, tmp);
                used[v] = 0;
            }
            Search(n, adj, used, v + 1, best, cur, depth + 1, tmp);
        }

        private static bool CanIncludeNode(int n, bool* adj, int* used, int v)
        {
            for (int u = 0; u < n; u++)
                if (adj[v * n + u] && used[u] != 0) return false;
            return true;
        }
    }
}

cs_files.MinSetCover.cs:
namespace IAFahim.Optimization.Exact
{
    using System.Runtime.CompilerServices;

    public static unsafe class MinSetCover
    {
        public static int Run(int m, int** sets, int* setSizes, int* covered, int* best, int* cur)
        {
            int universe = CalculateDistinctElements(m, sets, setSizes, covered);
            *best = m + 1;
            cur[0] = 0;
            Search(m, sets, setSizes, covered, 0, 0, best, cur, 0, universe);
            return *best;
        }

        private static int CalculateDistinctElements(int m, int** sets, int* setSizes, int* covered)
        {
            int distinct = 0;
            for (int i = 0; i < m; i++)
            {
                int sz = setSizes[i];
                int* s = sets[i];
                for (int j = 0; j < sz; j++)
                {
                    int elem = s[j];
                    if (covered[elem] == 0) { covered[elem] = 1; distinct++; }
                }
            }
            for (int i = 0; i < m; i++)
            {
                int sz = setSizes[i];
                int* s = sets[i];
                for (int j = 0; j < sz; j++) covered[s[j]] = 0;
            }
            return distinct;
        }

        private static void Search(int m, int** sets, int* setSizes, int* covered, int covCount, int used, int* best, int* cur, int idx, int remain)
        {
            if (used >= *best) return;
            if (covCount == remain) { *best = used; return; }
            if (idx == m) return;

            for (int i = idx; i < m; i++)
            {
                int added = CoverSet(i, sets, setSizes, covered);
                if (added > 0)
                {
                    cur[used] = i;
                    Search(m, sets, setSizes, covered, covCount + added, used + 1, best, cur, i + 1, remain);
                }
                UncoverSet(i, sets, setSizes, covered);
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int CoverSet(int i, int** sets, int* setSizes, int* covered)
        {
            int added = 0;
            int sz = setSizes[i];
            int* s = sets[i];
            for (int j = 0; j < sz; j++)
            {
                int elem = s[j];
                if (covered[elem] == 0) added++;
                covered[elem]++;
            }
            return added;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void UncoverSet(int i, int** sets, int* setSizes, int* covered)
        {
            int sz = setSizes[i];
            int* s = sets[i];
            for (int j = 0; j < sz; j++) covered[s[j]]--;
        }
    }
}

cs_files.MaximumClique.cs:
namespace IAFahim.Optimization.Exact
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class MaximumClique
    {
        public static int Run(int n, bool* adj, int* cand, int candSize, int* sol, long* dp, int* best, int* tmp)
        {
            long timer = 0;
            return Search(n, adj, cand, candSize, 0, sol, 0, best, dp, ref timer, tmp);
        }

        private static int Search(int n, bool* adj, int* cand, int candSize, int depth, int* sol, int solSize, int* best, long* dp, ref long timer, int* tmp)
        {
            if (ShouldStop(ref timer, solSize, candSize, best)) return 0;
            if (candSize == 0) { if (solSize > *best) { *best = solSize; return 1; } return 0; }

            int* currentTmp = tmp + depth * n;
            CopyCandidates(candSize, cand, currentTmp);

            while (candSize > 0)
            {
                if (solSize + candSize <= *best) return 0;
                int v = currentTmp[0];
                int nextCandSize = FilterNeighbors(n, v, candSize, currentTmp, cand, adj);

                sol[solSize] = v;
                Search(n, adj, cand, nextCandSize, depth + 1, sol, solSize + 1, best, dp, ref timer, tmp);

                RemoveCandidate(ref candSize, currentTmp, v);
            }
            return 0;
        }

        private static bool ShouldStop(ref long timer, int solSize, int candSize, int* best)
        {
            timer++;
            return solSize + candSize <= *best;
        }

        private static void CopyCandidates(int candSize, int* src, int* dst)
        {
            for (int i = 0; i < candSize; i++) dst[i] = src[i];
        }

        private static int FilterNeighbors(int n, int v, int candSize, int* currentTmp, int* nextCand, bool* adj)
        {
            int sz = 0;
            for (int i = 0; i < candSize; i++)
                if (adj[v * n + currentTmp[i]]) nextCand[sz++] = currentTmp[i];
            return sz;
        }

        private static void RemoveCandidate(ref int candSize, int* currentTmp, int v)
        {
            candSize--;
            int last = currentTmp[candSize];
            for (int i = 0; i < candSize; i++)
                if (currentTmp[i] == v) currentTmp[i] = last;
        }
    }
}

cs_files.HamiltonianPath.cs:
namespace IAFahim.Optimization.Exact
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class HamiltonianPath
    {
        public static long Run(int n, long* w, long inf, long* dp, int* perm)
        {
            InitializePathDp(n, inf, dp);
            int size = 1 << n;
            for (int mask = 1; mask < size; mask++)
            {
                ProcessPathMask(n, w, inf, dp, mask);
            }
            return FindMinBestPath(n, inf, dp, size - 1);
        }

        private static void InitializePathDp(int n, long inf, long* dp)
        {
            for (int i = 0; i < (1 << n) * n; i++) dp[i] = inf;
            for (int v = 0; v < n; v++) dp[(1 << v) * n + v] = 0;
        }

        private static void ProcessPathMask(int n, long* w, long inf, long* dp, int mask)
        {
            for (int v = 0; v < n; v++)
            {
                if ((mask & (1 << v)) == 0 || dp[mask * n + v] >= inf) continue;
                TryExtendPath(n, w, inf, dp, mask, v);
            }
        }

        private static void TryExtendPath(int n, long* w, long inf, long* dp, int mask, int v)
        {
            for (int u = 0; u < n; u++)
            {
                if ((mask & (1 << u)) != 0 || w[v * n + u] >= inf) continue;
                long cand = dp[mask * n + v] + w[v * n + u];
                if (cand < dp[(mask | (1 << u)) * n + u]) dp[(mask | (1 << u)) * n + u] = cand;
            }
        }

        private static long FindMinBestPath(int n, long inf, long* dp, int fullMask)
        {
            long best = inf;
            for (int v = 0; v < n; v++) if (dp[fullMask * n + v] < best) best = dp[fullMask * n + v];
            return best;
        }
    }
}

