namespace IAFahim.Optimization.Exact
{
    using System;

    public static unsafe class MinDominatingSet
    {
        public static int Run(int n, bool* adj, int* dom, int* best, int* tmp)
        {
            for (int i = 0; i < n; i++) dom[i] = 0;
            for (int i = 0; i < n; i++) tmp[i] = i;
            *best = n + 1;
            Search(n, adj, dom, 0, 0, best, tmp);
            return *best;
        }

        private static void Search(int n, bool* adj, int* dom, int idx, int used, int* best, int* order)
        {
            if (idx == n)
            {
                for (int vi = 0; vi < n; vi++)
                    if (dom[vi] == 0) return;
                if (used < *best) *best = used;
                return;
            }
            int vi2 = order[idx];
            if (dom[vi2] > 0)
            {
                Search(n, adj, dom, idx + 1, used, best, order);
                return;
            }
            dom[vi2]++;
            for (int u = 0; u < n; u++)
                if (adj[vi2 * n + u]) dom[u]++;
            Search(n, adj, dom, idx + 1, used + 1, best, order);
            dom[vi2]--;
            for (int u = 0; u < n; u++)
                if (adj[vi2 * n + u]) dom[u]--;
        }
    }
}

cs_files.HamiltonianCycle.cs:
namespace IAFahim.Optimization.Exact
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class HamiltonianCycle
    {
        public static long Run(int n, long* w, long inf, long* dp)
        {
            if (n < 3) return inf;
            int size = 1 << n;
            for (int i = 0; i < size * n; i++) dp[i] = inf;
            dp[(1 << 0) * n + 0] = 0;
            for (int mask = 1; mask < size; mask++)
            {
                ProcessCycleMask(n, w, inf, dp, mask);
            }
            return FindMinBestCycle(n, w, inf, dp, size - 1);
        }

        private static void ProcessCycleMask(int n, long* w, long inf, long* dp, int mask)
        {
            for (int last = 0; last < n; last++)
            {
                if ((mask & (1 << last)) == 0 || dp[mask * n + last] >= inf) continue;
                TryExtendPath(n, w, inf, dp, mask, last);
            }
        }

        private static void TryExtendPath(int n, long* w, long inf, long* dp, int mask, int last)
        {
            for (int u = 0; u < n; u++)
            {
                if ((mask & (1 << u)) != 0 || w[last * n + u] >= inf) continue;
                long cand = dp[mask * n + last] + w[last * n + u];
                if (cand < dp[(mask | (1 << u)) * n + u]) dp[(mask | (1 << u)) * n + u] = cand;
            }
        }

        private static long FindMinBestCycle(int n, long* w, long inf, long* dp, int fullMask)
        {
            long best = inf;
            for (int last = 1; last < n; last++)
            {
                if (dp[fullMask * n + last] >= inf || w[last * n + 0] >= inf) continue;
                long cand = dp[fullMask * n + last] + w[last * n + 0];
                if (cand < best) best = cand;
            }
            return best;
        }
    }
}

cs_files.TspBitonic.cs:
namespace IAFahim.Optimization.Exact
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class TspBitonic
    {
        private static long Dist(double x1, double y1, double x2, double y2)
        {
            double dx = x1 - x2, dy = y1 - y2;
            return (long)Math.Sqrt(dx * dx + dy * dy);
        }

        public static long Run(int n, double* xs, double* ys, long* dp)
        {
            if (n < 2) return 0;
            for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                dp[i * n + j] = long.MaxValue;
            dp[0 * n + 1] = Dist(xs[0], ys[0], xs[1], ys[1]);
            dp[1 * n + 0] = dp[0 * n + 1];
            for (int i = 2; i < n; i++)
            {
                for (int j = 0; j < i; j++)
                {
                    long prev = dp[j * n + i - 1];
                    if (j == i - 1)
                    {
                        long best = long.MaxValue;
                        for (int k = 0; k < i - 1; k++)
                        {
                            long d = dp[k * n + i - 1];
                            if (d != long.MaxValue)
                            {
                                long cand = d + Dist(xs[k], ys[k], xs[i], ys[i]);
                                if (cand < best) best = cand;
                            }
                        }
                        dp[j * n + i] = best;
                    }
                    else if (prev != long.MaxValue)
                    {
                        dp[j * n + i] = prev + Dist(xs[i - 1], ys[i - 1], xs[i], ys[i]);
                    }
                    dp[i * n + j] = dp[j * n + i];
                }
            }
            long dLast = dp[0 * n + n - 1];
            if (dLast != long.MaxValue)
                return dLast + Dist(xs[0], ys[0], xs[n - 1], ys[n - 1]);
            return long.MaxValue;
        }
    }
}

