namespace IAFahim.Optimization.Knapsack
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class MeetInMiddle
    {
        private const int MaxItems = 40;
        private const int WeightValueStride = 2;

        public static long Run(long* w, long* v, int n, long cap, long* left)
        {
            if (n <= MaxItems)
            {
                int half = n >> 1;
                int leftCount = 1 << half;
                FillLeftTable(w, v, half, leftCount, left);
                long best = 0;
                int rightCount = 1 << (n - half);
                for (int mask = 0; mask < rightCount; mask++)
                {
                    AccumulateSubset(w, v, half, n - half, mask, out long sw, out long sv);
                    long rem = cap - sw;
                    if (rem < 0) continue;
                    long bestLeft = BestLeftValue(left, leftCount, rem);
                    long cand = sv + bestLeft;
                    if (cand > best) best = cand;
                }
                return best;
            }
            return 0;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void FillLeftTable(long* w, long* v, int half, int leftCount, long* left)
        {
            for (int i = 0; i < leftCount; i++)
            {
                AccumulateSubset(w, v, 0, half, i, out long sw, out long sv);
                left[i * WeightValueStride] = sw;
                left[i * WeightValueStride + 1] = sv;
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void AccumulateSubset(long* w, long* v, int offset, int count, int mask, out long sw, out long sv)
        {
            sw = 0;
            sv = 0;
            for (int j = 0; j < count; j++)
            {
                if ((mask & (1 << j)) != 0)
                {
                    sw += w[offset + j];
                    sv += v[offset + j];
                }
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static long BestLeftValue(long* left, int leftCount, long rem)
        {
            long bestLeft = 0;
            for (int i = 0; i < leftCount; i++)
                if (left[i * WeightValueStride] <= rem && left[i * WeightValueStride + 1] > bestLeft)
                    bestLeft = left[i * WeightValueStride + 1];
            return bestLeft;
        }
    }
}

