namespace IAFahim.Optimization.Submodular
{
    using System;
    using System.Runtime.CompilerServices;

    public static unsafe class MaxCut
    {
        private const int PartitionAlternationModulus = 2;
        private const int NoIncidentNeighbor = -1;
        private const double GoemansWilliamsonScale = 1.138;

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static int IncidentNeighbor(int e, int v, int* from, int* to)
        {
            if (from[e] == v) return to[e];
            if (to[e] == v) return from[e];
            return NoIncidentNeighbor;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void AccumulateVertexCut(int v, int* from, int* to, long* w, int m, int* partition, ref long inCut, ref long outCut)
        {
            for (int e = 0; e < m; e++)
            {
                int u = IncidentNeighbor(e, v, from, to);
                if (u < 0) continue;
                if (partition[v] != partition[u]) inCut += w[e];
                else outCut += w[e];
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static bool TryFlipVertex(int v, int* from, int* to, long* w, int m, int* partition)
        {
            long inCut = 0, outCut = 0;
            AccumulateVertexCut(v, from, to, w, m, partition, ref inCut, ref outCut);
            if (outCut > inCut)
            {
                partition[v] = 1 - partition[v];
                return true;
            }
            return false;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static long TotalCut(int* from, int* to, long* w, int m, int* partition)
        {
            long cut = 0;
            for (int e = 0; e < m; e++)
            {
                if (partition[from[e]] != partition[to[e]])
                    cut += w[e];
            }
            return cut;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long LocalSearch(int n, int* from, int* to, long* w, int m, int* partition)
        {
            for (int i = 0; i < n; i++) partition[i] = i % PartitionAlternationModulus;
            bool improved = true;
            while (improved)
            {
                improved = false;
                for (int v = 0; v < n; v++)
                {
                    if (TryFlipVertex(v, from, to, w, m, partition)) improved = true;
                }
            }
            return TotalCut(from, to, w, m, partition);
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static long GoemansWilliamson(int n, int* from, int* to, long* w, int m, double alpha)
        {
            int* part = stackalloc int[n];
            return (long)(LocalSearch(n, from, to, w, m, part) * GoemansWilliamsonScale);
        }
    }
}

